import{_ as i,C as a,o as r,c,j as t,a as s,E as n,a6 as l}from"./chunks/framework.CD0vXS2f.js";const b=JSON.parse('{"title":"05 · D1–D12 Data Readiness Standard & Automated CI Gates","description":"12-point enterprise AI Data Strategy readiness standard (D1–D12) backed by the zero-dependency data_readiness_gate.py CLI (DRG001–DRG007) and data-grounding-freshness-gate.kql workbook.","frontmatter":{"title":"05 · D1–D12 Data Readiness Standard & Automated CI Gates","description":"12-point enterprise AI Data Strategy readiness standard (D1–D12) backed by the zero-dependency data_readiness_gate.py CLI (DRG001–DRG007) and data-grounding-freshness-gate.kql workbook."},"headers":[],"relativePath":"playbooks/ai-data-strategy/05-data-governance-release-gates.md","filePath":"playbooks/ai-data-strategy/05-data-governance-release-gates.md","lastUpdated":1795642852816,"verifiedStamp":"2026-11-25 13:40 PST"}'),g={name:"playbooks/ai-data-strategy/05-data-governance-release-gates.md"};function p(h,e,u,y,m,f){const o=a("PlaybookMeta"),d=a("PageBrief");return r(),c("div",null,[e[0]||(e[0]=t("h1",{id:"_05-·-d1–d12-data-readiness-standard-automated-ci-gates",tabindex:"-1"},[s("05 · "),t("code",null,"D1–D12"),s(" Data Readiness Standard & Automated CI Gates "),t("a",{class:"header-anchor",href:"#_05-·-d1–d12-data-readiness-standard-automated-ci-gates","aria-label":'Permalink to "05 · `D1–D12` Data Readiness Standard & Automated CI Gates"'},"​")],-1)),n(o,{track:"05 · AI Data Strategy, Fabric–Foundry & Governance",verified:"2026-11-23 19:30 PST",status:"Live v2.0",studioHref:"/studio/#data-strategy",studioLabel:"Data Strategy Advisor →",kitHref:"/papers/engineering-kits#data-gate",kitLabel:"data_readiness_gate.py →"}),n(d,{stage:"govern",readTime:"5 min read",problem:"Data governance standards written only in slide decks break down as soon as teams add a new SharePoint connector, change an embedding model, or onboard a new tenant without checking Purview labels and ACL tombstoning.",takeaway:"Enforce the 12-point D1–D12 standard in every release pipeline using the zero-dependency data_readiness_gate.py CLI (DRG001–DRG007) and monitor live drift with data-grounding-freshness-gate.kql.",csaUse:"Wire data_readiness_gate.py into PR / pre-cutover pipelines and include D1–D12 in the Architecture Review Board sign-off checklist."}),e[1]||(e[1]=l('<h2 id="_1-the-12-point-ai-data-readiness-standard-d1–d12" tabindex="-1">1. The 12-Point AI Data Readiness Standard (<code>D1–D12</code>) <a class="header-anchor" href="#_1-the-12-point-ai-data-readiness-standard-d1–d12" aria-label="Permalink to &quot;1. The 12-Point AI Data Readiness Standard (`D1–D12`)&quot;">​</a></h2><table tabindex="0"><thead><tr><th style="text-align:left;">Gate</th><th style="text-align:left;">Readiness Control</th><th style="text-align:left;">Verification Method</th><th style="text-align:left;">Evidence</th></tr></thead><tbody><tr><td style="text-align:left;"><strong><code>D1</code></strong></td><td style="text-align:left;"><strong>Dual-Path Store Routing Contract:</strong> Structured KPIs/analytics route to <strong>Fabric IQ</strong>; unstructured document corpora route to <strong>Azure AI Search (<code>Foundry IQ</code>)</strong>; tenant-scoped operational memory routes to <strong>Cosmos DB (<code>DiskANN</code> + <code>RRF</code>)</strong>.</td><td style="text-align:left;">Architecture review + <code>DRG002</code> store-target contract check</td><td style="text-align:left;"><span class="ev-badge ev-arch">[Arch]</span></td></tr><tr><td style="text-align:left;"><strong><code>D2</code></strong></td><td style="text-align:left;"><strong>OneLake Zero-Copy Lineage &amp; AI-Ready Gold:</strong> Every grounded dataset carries <code>medallion_tier</code> (<code>gold</code> / <code>ai-gold</code>), <code>source_uri</code>, and <code>lineage_sha256</code> without shadow lake copies.</td><td style="text-align:left;"><code>data_readiness_gate.py</code> (<code>DRG002</code>)</td><td style="text-align:left;"><span class="ev-badge ev-m">[M]</span> <span class="ev-badge ev-arch">[Arch]</span></td></tr><tr><td style="text-align:left;"><strong><code>D3</code></strong></td><td style="text-align:left;"><strong>Fabric F-SKU Interactive Isolation:</strong> Interactive <code>Fabric IQ</code> / Data Agent queries run on a dedicated interactive F-SKU (<code>&lt;=65%</code> steady CU) separated from batch Spark ETL via OneLake Shortcuts.</td><td style="text-align:left;">Fabric Capacity Metrics + <code>DRG002</code> + <code>data-grounding-freshness-gate.kql</code></td><td style="text-align:left;"><span class="ev-badge ev-arch">[Arch]</span> <span class="ev-badge ev-agree">[Agree]</span></td></tr><tr><td style="text-align:left;"><strong><code>D4</code></strong></td><td style="text-align:left;"><strong>Purview DSPM for AI Active:</strong> Oversharing scan completed prior to indexing; Foundry &amp; Fabric interaction audit, sensitivity-label tracking, and DLP policies active.</td><td style="text-align:left;">Purview DSPM portal + <code>DRG003</code></td><td style="text-align:left;"><span class="ev-badge ev-m">[M]</span></td></tr><tr><td style="text-align:left;"><strong><code>D5</code></strong></td><td style="text-align:left;"><strong>Sensitivity Label &amp; Entra ACL Inheritance:</strong> Every non-public chunk/document carries an explicit <code>sensitivity_label</code> and non-empty <code>acl_group_ids</code>; restricted labels never allow <code>allow_public_index=true</code>.</td><td style="text-align:left;"><code>data_readiness_gate.py</code> (<code>DRG003</code>, <code>DRG004</code>)</td><td style="text-align:left;"><span class="ev-badge ev-m">[M]</span> <span class="ev-badge ev-arch">[Arch]</span></td></tr><tr><td style="text-align:left;"><strong><code>D6</code></strong></td><td style="text-align:left;"><strong>Event-Driven ACL Revocation &amp; Tombstoning SLA:</strong> Revocation lag verified <code>&lt;=15 min</code> (enterprise) or <code>&lt;=5 min</code> (regulated ethical-wall) across primary and DR stamps with zero overdue unpurged tombstones.</td><td style="text-align:left;"><code>DRG004</code> + <code>data-grounding-freshness-gate.kql</code></td><td style="text-align:left;"><span class="ev-badge ev-agree">[Agree]</span></td></tr><tr><td style="text-align:left;"><strong><code>D7</code></strong></td><td style="text-align:left;"><strong>Cosmos DB Vector/Hybrid Immutability &amp; Partition Isolation:</strong> <code>DiskANN</code> / <code>quantizedFlat</code> / <code>flat</code> policy + <code>FullTextScore</code> <code>RRF</code> verified; single-partition <code>/tenantEngagementId</code> key prevents cross-tenant scatter-gather.</td><td style="text-align:left;">Cosmos container policy + <code>DRG005</code></td><td style="text-align:left;"><span class="ev-badge ev-m">[M]</span> <span class="ev-badge ev-arch">[Arch]</span></td></tr><tr><td style="text-align:left;"><strong><code>D8</code></strong></td><td style="text-align:left;"><strong>Zero-Downtime Alias / Blue-Green Cutover &amp; Re-Embedding Budget:</strong> AI Search index alias or Cosmos blue-green container cutover configured; re-embedding token surge routed through dedicated batch TPM quota.</td><td style="text-align:left;">Decision Studio surge calc + <code>DRG005</code></td><td style="text-align:left;"><span class="ev-badge ev-m">[M]</span> <span class="ev-badge ev-arch">[Arch]</span></td></tr><tr><td style="text-align:left;"><strong><code>D9</code></strong></td><td style="text-align:left;"><strong>Layout-Aware Ingestion Fidelity:</strong> Binary documents parsed via Azure AI Content Understanding into bounded chunks (<code>128–2,048</code> tokens default) with deterministic <code>chunk_sha256</code> IDs.</td><td style="text-align:left;"><code>data_readiness_gate.py</code> (<code>DRG006</code>)</td><td style="text-align:left;"><span class="ev-badge ev-m">[M]</span> <span class="ev-badge ev-arch">[Arch]</span></td></tr><tr><td style="text-align:left;"><strong><code>D10</code></strong></td><td style="text-align:left;"><strong>Corpus Anti-Poisoning &amp; Injection Hygiene:</strong> Automated pre-index scanner rejects indirect prompt-injection override markers and excessive duplicate/empty chunk ratios (<code>&lt;=5%</code>).</td><td style="text-align:left;"><code>data_readiness_gate.py</code> (<code>DRG006</code>)</td><td style="text-align:left;"><span class="ev-badge ev-arch">[Arch]</span></td></tr><tr><td style="text-align:left;"><strong><code>D11</code></strong></td><td style="text-align:left;"><strong>Pos 6 Cache-Safe Ordering &amp; Regional Freshness Parity:</strong> Retrieved chunks injected strictly at Pos 6 (preserving Playbook 01 prefix reuse); dual-region Search/Cosmos lag stays <code>&lt;1%</code>.</td><td style="text-align:left;"><code>DRG005</code>, <code>DRG007</code> + <code>pcr_lint.py</code> (<code>PCR004</code>)</td><td style="text-align:left;"><span class="ev-badge ev-arch">[Arch]</span></td></tr><tr><td style="text-align:left;"><strong><code>D12</code></strong></td><td style="text-align:left;"><strong>OTel-to-Fabric Eval Flywheel &amp; Automated PR Gate:</strong> Anonymized retrieval/grounding failures feed OneLake Gold eval fixtures; <code>data_readiness_gate.py</code> runs in CI and exits <code>0</code> before promotion.</td><td style="text-align:left;">CI workflow + <code>DRG007</code> + KQL workbook</td><td style="text-align:left;"><span class="ev-badge ev-agree">[Agree]</span></td></tr></tbody></table><hr><h2 id="drg-contract" tabindex="-1">2. Deterministic CI Verification: <code>data_readiness_gate.py</code> (<code>DRG001–DRG007</code>) <a class="header-anchor" href="#drg-contract" aria-label="Permalink to &quot;2. Deterministic CI Verification: `data_readiness_gate.py` (`DRG001–DRG007`) {#drg-contract}&quot;">​</a></h2><p>The MIT-licensed, zero-dependency Python 3 CLI (<a href="/enterprise-azure-ai-hub/papers/engineering-kits#data-gate"><code>docs/public/kits/data_readiness_gate.py</code></a>) validates an exported data-plane snapshot JSON against a contract exported from the <a href="/enterprise-azure-ai-hub/studio/#data-strategy">Interactive Data Strategy Advisor</a>.</p><h3 id="rule-reference-fail-closed-exit-semantics" tabindex="-1">Rule Reference &amp; Fail-Closed Exit Semantics <a class="header-anchor" href="#rule-reference-fail-closed-exit-semantics" aria-label="Permalink to &quot;Rule Reference &amp; Fail-Closed Exit Semantics&quot;">​</a></h3><ul><li><strong>Exit <code>0</code> (<code>PASS</code>):</strong> Every declared dataset/corpus passed all configured <code>DRG001–DRG007</code> contracts.</li><li><strong>Exit <code>1</code> (<code>BLOCKED — Gate Violation</code>):</strong> Valid JSON inputs violated one or more readiness rules (<code>DRG001–DRG007</code>).</li><li><strong>Exit <code>2</code> (<code>BLOCKED — Invalid Input / Contract</code>):</strong> Unreadable file, invalid UTF-8, duplicate JSON object keys (including nested objects), unquoted non-standard numeric constants, excessive JSON nesting, malformed/unknown top-level contract fields, or contradictory threshold bounds—never silently downgraded to defaults <span class="ev-badge ev-arch">[Arch]</span>.</li></ul><table tabindex="0"><thead><tr><th style="text-align:left;">Rule ID</th><th style="text-align:left;">Deterministic Check Enforced</th></tr></thead><tbody><tr><td style="text-align:left;"><strong><code>DRG001</code></strong></td><td style="text-align:left;">Snapshot schema integrity, non-empty <code>datasets[]</code>, unique <code>source_id</code> entries, optional exact <code>expected_source_ids</code> inventory, explicit types/booleans, finite numeric bounds.</td></tr><tr><td style="text-align:left;"><strong><code>DRG002</code></strong></td><td style="text-align:left;">Fabric / OneLake lineage (<code>medallion_tier</code> in <code>gold</code>/<code>ai-gold</code>, non-empty <code>source_uri</code>, and exactly 64 ASCII hexadecimal characters in <code>lineage_sha256</code>), valid <code>store_target</code> (<code>fabric-iq</code>, <code>ai-search</code>, <code>cosmos-hybrid</code>), and <code>dedicated_interactive_fsku=true</code> when <code>fabric-iq</code> is enabled.</td></tr><tr><td style="text-align:left;"><strong><code>DRG003</code></strong></td><td style="text-align:left;">Microsoft Purview DSPM for AI active (<code>purview_dspm_enabled=true</code>), valid non-empty <code>sensitivity_label</code> on every dataset, and zero restricted datasets (<code>Confidential</code> / <code>Highly Confidential</code>) marked <code>allow_public_index=true</code>.</td></tr><tr><td style="text-align:left;"><strong><code>DRG004</code></strong></td><td style="text-align:left;">Entra ACL enforcement (<code>acl_enforced=true</code>), non-empty <code>acl_group_ids</code> on non-public datasets, <code>revocation_lag_minutes &lt;= max_revocation_lag_min</code> (<code>15</code> enterprise / <code>5</code> regulated), and zero overdue tombstones (<code>overdue_tombstones == 0</code>).</td></tr><tr><td style="text-align:left;"><strong><code>DRG005</code></strong></td><td style="text-align:left;">Store-specific production parity: <code>cosmos-hybrid</code> requires <code>vector_index_type</code> in <code>{&quot;diskANN&quot;, &quot;quantizedFlat&quot;, &quot;flat&quot;}</code>, <code>hybrid_rrf_enabled=true</code>, <code>tenant_partition_key_scoped=true</code>, and consistent positive-integer <code>embedding_dim</code> within the selected index limit (<code>flat</code>: <code>505</code>; <code>quantizedFlat</code>/<code>diskANN</code>: <code>4096</code>); <code>ai-search</code> requires <code>alias_cutover_enabled=true</code> and <code>region_lag_pct &lt;= max_region_lag_pct</code>.</td></tr><tr><td style="text-align:left;"><strong><code>DRG006</code></strong></td><td style="text-align:left;">Corpus hygiene &amp; anti-poisoning: <code>avg_chunk_tokens</code> within <code>[min_chunk_tokens, max_chunk_tokens]</code>, <code>duplicate_or_empty_ratio_pct &lt;= max_duplicate_ratio_pct</code>, and zero indirect prompt-injection signatures in <code>sample_chunks[]</code>.</td></tr><tr><td style="text-align:left;"><strong><code>DRG007</code></strong></td><td style="text-align:left;">Grounding freshness &amp; cache-safe flywheel: <code>freshness_lag_minutes &lt;= max_freshness_lag_min</code>, <code>pos6_cache_safe_ordering=true</code>, and <code>eval_flywheel_enabled=true</code> when required by contract.</td></tr></tbody></table><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># Run offline self-test suite (zero external dependencies)</span></span>\n<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">python3</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> docs/public/kits/data_readiness_gate.py</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --self-test</span></span>\n<span class="line"></span>\n<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># Evaluate a pre-cutover data-plane snapshot against a Decision Studio contract</span></span>\n<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">python3</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> docs/public/kits/data_readiness_gate.py</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> ./artifacts/data-snapshot.json</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> \\</span></span>\n<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  --contract</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> ./data-readiness-contract.json</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --json</span></span></code></pre></div><hr><h3 id="strict-json-constants" tabindex="-1">Strict JSON Numeric Constants (<code>DRG001</code>) <a class="header-anchor" href="#strict-json-constants" aria-label="Permalink to &quot;Strict JSON Numeric Constants (`DRG001`) {#strict-json-constants}&quot;">​</a></h3><p>Both the acceptance contract and data snapshot reject unquoted <code>NaN</code>, <code>Infinity</code>, and <code>-Infinity</code> anywhere, including ignored root metadata and metadata in a later dataset after otherwise valid evidence. These inputs exit <code>2</code> before snapshot evaluation, with no stdout or partial readiness report. The diagnostic identifies the input role without echoing paths, member names, or constant values. Invalid contract JSON is rejected before the snapshot file is read <span class="ev-badge ev-arch">[Arch]</span>.</p><p>Quoted strings such as <code>&quot;NaN&quot;</code>, ordinary JSON scalars, and nested metadata remain supported. This is a local JSON-integrity policy, not a Microsoft service requirement, metadata-schema validator, or evidence-authenticity check. Standard JSON numbers that overflow floating-point parsing are not rejected by this constant rule; existing finite-number checks still apply to enforced numeric fields <span class="ev-badge ev-arch">[Arch]</span>.</p><p>Offline regressions exercise all three constants in enforced fields and ignored nested metadata for both inputs, text/JSON CLI exit <code>2</code>, contract-before-snapshot validation, and exit <code>0</code> recovery with valid metadata. They run through <code>node scripts/run-python.mjs docs/public/kits/data_readiness_gate.py --self-test</code> in <code>npm run verify</code>, without live Azure access <span class="ev-badge ev-val">[Validate]</span>.</p><h3 id="expected-source-inventory" tabindex="-1">Approved Dataset Inventory (<code>DRG001</code>) <a class="header-anchor" href="#expected-source-inventory" aria-label="Permalink to &quot;Approved Dataset Inventory (`DRG001`) {#expected-source-inventory}&quot;">​</a></h3><p>An optional <code>expected_source_ids</code> contract field blocks a clean subset or substituted corpus from passing readiness. <code>required_stores</code> checks store coverage, not dataset completeness: several required corpora can share the same store. Approve the inventory independently of the submitted snapshot <span class="ev-badge ev-arch">[Arch]</span>.</p><div class="language-json vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">json</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">{</span></span>\n<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  &quot;expected_source_ids&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: [</span></span>\n<span class="line"><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">    &quot;fabric-finance-kpis&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,</span></span>\n<span class="line"><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">    &quot;search-regulatory-corpus&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,</span></span>\n<span class="line"><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">    &quot;cosmos-agent-episodic-memory&quot;</span></span>\n<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">  ]</span></span>\n<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">}</span></span></code></pre></div><p>Every expected identifier must appear exactly once, with no unexpected identifiers; matching is exact and case-sensitive, and dataset order is irrelevant. Existing duplicate-source checks remain active. Missing or unexpected sources produce <code>DRG001</code> and exit <code>1</code>, preserving other findings and dataset counts. Inventory diagnostics use counts and dataset ordinals, never the missing or unexpected identifier values <span class="ev-badge ev-arch">[Arch]</span>.</p><p>The field must be a non-empty array of unique, non-empty strings without leading or trailing whitespace. Invalid inventories exit <code>2</code> with no stdout before snapshot evidence is read. Omission preserves existing defaults and Decision Studio exports; <code>null</code> and empty arrays do not disable the check. This local acceptance contract verifies declared inventory completeness, not artifact authenticity, live connector access, or source-content quality <span class="ev-badge ev-arch">[Arch]</span>.</p><p>The kit&#39;s offline self-test covers reordered complete snapshots, omitted and substituted datasets, duplicate entries, combined governance failures, and invalid inventory types in text and JSON CLI modes. It runs through <code>node scripts/run-python.mjs docs/public/kits/data_readiness_gate.py --self-test</code> in <code>npm run verify</code> <span class="ev-badge ev-val">[Validate]</span>.</p><h3 id="lineage-digest-syntax" tabindex="-1">Lineage Digest Syntax (<code>DRG002</code>) <a class="header-anchor" href="#lineage-digest-syntax" aria-label="Permalink to &quot;Lineage Digest Syntax (`DRG002`) {#lineage-digest-syntax}&quot;">​</a></h3><p>Every dataset, across all three store targets, must supply <code>lineage_sha256</code> as exactly 64 ASCII hexadecimal characters (<code>0–9</code>, <code>a–f</code>, <code>A–F</code>). Lowercase, uppercase, and mixed-case digests are accepted without normalization. Missing values, non-string types, placeholders, incorrect lengths, non-hex characters, and surrounding or embedded whitespace produce <code>DRG002</code> and exit <code>1</code>; other findings and dataset counts remain intact. The diagnostic identifies the dataset ordinal and field without echoing the digest or source identifier <span class="ev-badge ev-arch">[Arch]</span>.</p><p>This is a local lineage-metadata syntax contract, not a Microsoft service requirement. Generate the digest from an independently defined lineage artifact and retain that artifact for review: the gate does not recompute hashes, authenticate provenance, compare approved lineage pins, or prove zero-copy ingestion. A syntactically valid fabricated or stale digest can still pass <span class="ev-badge ev-arch">[Arch]</span>.</p><p>Offline self-tests cover missing and malformed values for every store, valid casing and recovery, combined governance failures, and text/JSON CLI exit codes with non-echoing diagnostics. Existing sample snapshots and Decision Studio contract exports remain compatible. These regressions run in <code>npm run verify</code>, without accessing live Fabric, Search, or Cosmos resources <span class="ev-badge ev-val">[Validate]</span>.</p><h3 id="cosmos-dimension-limits" tabindex="-1">Cosmos Vector Index Dimension Limits (<code>DRG005</code>) <a class="header-anchor" href="#cosmos-dimension-limits" aria-label="Permalink to &quot;Cosmos Vector Index Dimension Limits (`DRG005`) {#cosmos-dimension-limits}&quot;">​</a></h3><p>Azure Cosmos DB for NoSQL supports at most <strong>505 dimensions</strong> for <code>flat</code> vector indexes and <strong>4,096 dimensions</strong> for <code>quantizedFlat</code> and <code>diskANN</code>, according to the <a href="https://learn.microsoft.com/en-us/azure/cosmos-db/vector-search#vector-indexing-policies" target="_blank" rel="noreferrer">published vector-index limits</a> <span class="ev-badge ev-m">[M]</span>.</p><p>For each <code>cosmos-hybrid</code> dataset, <code>DRG005</code> requires a positive integer <code>embedding_dim</code> no greater than the selected index&#39;s limit. A <code>flat</code> index with <code>1536</code> or <code>3072</code> dimensions therefore blocks readiness even though those are valid Decision Studio sizing presets. Oversized dimensions exit <code>1</code>, with dataset ordinals rather than source identifiers in the new diagnostic; other findings and cross-dataset dimension consistency checks remain active. Fabric and AI Search datasets are unaffected <span class="ev-badge ev-arch">[Arch]</span>.</p><p>This offline metadata check does not inspect the deployed container policy, vector lengths, embedding-model compatibility, or retrieval recall. Choose a compatible index and embedding model before creating the container; passing this check does not prove live deployment readiness <span class="ev-badge ev-arch">[Arch]</span>.</p><p>Self-tests cover each index&#39;s inclusive upper boundary, one dimension above it, small valid dimensions, incompatible <code>flat</code> presets, malformed index types, combined governance/parity failures, and text/JSON CLI exit codes. They run through <code>node scripts/run-python.mjs docs/public/kits/data_readiness_gate.py --self-test</code> in <code>npm run verify</code>, without live Azure access <span class="ev-badge ev-val">[Validate]</span>.</p><h2 id="_3-continuous-production-drift-monitoring-data-grounding-freshness-gate-kql" tabindex="-1">3. Continuous Production Drift Monitoring (<code>data-grounding-freshness-gate.kql</code>) <a class="header-anchor" href="#_3-continuous-production-drift-monitoring-data-grounding-freshness-gate-kql" aria-label="Permalink to &quot;3. Continuous Production Drift Monitoring (`data-grounding-freshness-gate.kql`)&quot;">​</a></h2><p>Deploy <a href="/enterprise-azure-ai-hub/papers/engineering-kits#data-kql"><code>data-grounding-freshness-gate.kql</code></a> into Log Analytics / Application Insights to detect post-cutover regressions before users report stale answers:</p><ul><li><strong>Ingestion &amp; ACL Tombstoning Lag (<code>D6</code>, <code>D11</code>):</strong> Alerts when <code>MaxRevocationLagMin &gt; 15</code> (<code>&gt; 5</code> regulated) or <code>MaxFreshnessLagMin &gt; 60</code>.</li><li><strong>Purview DSPM Label Coverage (<code>D4</code>, <code>D5</code>):</strong> Fails immediately if <code>UnlabelledRetrievalCount &gt; 0</code>.</li><li><strong>Cosmos DB Hybrid RU &amp; Fabric CU Throttling (<code>D3</code>, <code>D7</code>):</strong> Tracks <code>Cosmos429RatePct</code>, p95 RU charge per hybrid query (flagging accidental cross-partition fan-out), and Fabric IQ <code>429</code>/CU delay events.</li><li><strong>Zero-Grounding Drift (<code>D12</code>):</strong> Surfaces rising empty-retrieval rates so missing OneLake shortcuts or broken indexers trigger automated alerting.</li></ul>',32))])}const k=i(g,[["render",p]]);export{b as __pageData,k as default};
